/**
 * @file tooltip-hidden-hint.tsx
 * @copyright 2026, Firaxis Games
 * @description First-time hint popup shown when the player hides tooltips via the hold-to-hide inspect action.
 * Shown once per user profile and persisted via UI.setOption.
 */

import { createMemo } from "solid-js";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { Button } from "#core/ui-next/components/button.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ModalFrame } from "#core/ui-next/components/modal-frame.jsx";
import { KBMNavHelp, NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { HotkeyIconContext, HotkeyIconContextProvider } from "#core/ui-next/services/hotkey.js";
import { IsKeyboardActive, IsMouseActive } from "#core/ui-next/services/input.js";

export const TOOLTIP_HIDDEN_HINT_SCREEN_ID = "tooltip-hidden-hint";

const TooltipHiddenHintComponent = () => {
	const close = () => ContextManager.pop(TOOLTIP_HIDDEN_HINT_SCREEN_ID);
	const isKBM = createMemo(() => IsKeyboardActive() || IsMouseActive());
	const hotkeyIconProvider: HotkeyIconContextProvider = { disabled: () => false, actionName: () => "toggle-tooltip" };

	const navHelp = () => {
		if (isKBM()) {
			return <KBMNavHelp actionName="keyboard-inspect-tooltip" />;
		}
		return (
			<NavHelp
				actionName="toggle-tooltip"
				class="size-8"
			/>
		);
	};

	return (
		<Panel
			name="Tooltip Hidden Hint"
			id={TOOLTIP_HIDDEN_HINT_SCREEN_ID}
			onCancelInput={close}
			class="fixed inset-0 flex items-center justify-center"
		>
			<ModalFrame class="flex flex-col items-center gap-4 max-w-sm">
				<div class="font-title text-base text-center uppercase">
					<L10n.Compose text="LOC_UI_TOOLTIP_HIDDEN_HINT_TITLE" />
				</div>
				<div class="font-body text-sm text-center">
					<HotkeyIconContext.Provider value={hotkeyIconProvider}>
						<span class="flex flex-row items-center justify-center gap-1">
							<L10n.Compose text="LOC_UI_TOOLTIP_HIDDEN_HINT_BODY_PRE" />
							{navHelp()}
							<L10n.Compose text="LOC_UI_TOOLTIP_HIDDEN_HINT_BODY_POST" />
						</span>
					</HotkeyIconContext.Provider>
				</div>
				<Button onActivate={close}>
					<L10n.Compose text="LOC_GENERIC_OK" />
				</Button>
			</ModalFrame>
		</Panel>
	);
};

ComponentRegistry.register({
	name: "TooltipHiddenHint",
	createInstance: TooltipHiddenHintComponent,
});

defineLegacyComponent(TOOLTIP_HIDDEN_HINT_SCREEN_ID, {}, () => {
	return <TooltipHiddenHintComponent />;
});
